  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--faint);
}
.launcher-n {
  color: var(--fg);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.launcher-h {
  color: var(--faint);
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}
.launcher-list .launcher-empty {
