  white-space: pre-wrap;
  line-height: 1.6;
}
.poweroff .press {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  color: #555;
  font-size: 12px;
  letter-spacing: 0.12em;
  animation: poweroff-blink 2.4s ease-in-out infinite;
