  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  color: var(--fg);
}
.cm-cal-h button {
  padding: 0 6px;
  color: var(--muted);
}
.cm-grid {
  display: grid;
  grid-template-columns: repeat(7, 28px);
  gap: 2px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.cm-grid span {
  line-height: 24px;
  border-radius: 5px;
  color: var(--fg);
}
.cm-grid .cm-dow {
  color: var(--faint);
  font-size: 10.5px;
}
.cm-grid .cm-today {
  background: var(--fg);
  color: var(--bg);
}
.cm-side {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-left: 1px solid var(--line);
  padding-left: 16px;
}
.cm-place {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.cm-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.cm-k {
  font-size: 10.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--faint);
}
.cm-v {
  color: var(--fg);
  font-variant-numeric: tabular-nums;
}
.cm-dim {
  color: var(--faint);
}
@media (max-width: 560px) {
  .clockmenu {
    grid-template-columns: 1fr;
  }
  .cm-side {
    border-left: 0;
    padding-left: 0;
    border-top: 1px solid var(--line);
    padding-top: 12px;
  }
}

/* swww-style wallpaper transition: the old wallpaper's snapshot, masked away */
.bg-swww {
  display: none;
  pointer-events: none;
  object-fit: fill;
}

/* ── notifications (mako / dunst style) ─────────────────── */
.notify {
  position: fixed;
  z-index: 60;
  top: calc(var(--bar-h) + env(safe-area-inset-top, 0px) + 10px);
  right: max(12px, env(safe-area-inset-right, 0px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(340px, calc(100vw - 24px));
  pointer-events: none;
}
:root[data-bar="bottom"] .notify {
  top: calc(env(safe-area-inset-top, 0px) + 12px);
}
.notify-card {
  pointer-events: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 14px;
  text-align: left;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--fg);
  background: color-mix(in srgb, var(--win-focus) 94%, transparent);
  border: 2px solid var(--line-focus);
  border-radius: var(--radius);
  box-shadow: 0 10px 30px rgb(0 0 0 / 0.35);
  animation: notify-in 260ms var(--ease) both;
}
.notify-card.out {
  animation: notify-out 240ms var(--ease) both;
}
.notify-app {
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.04em;
}
.notify-text {
  color: var(--muted);
  line-height: 1.45;
}
@keyframes notify-in {
  from {
    opacity: 0;
    transform: translateX(24px);
  }
}
@keyframes notify-out {
  to {
    opacity: 0;
    transform: translateX(24px);
  }
}

/* the terminal's shell greeting: label column + value */
.t-greet {
  display: grid;
  grid-template-columns: 5ch 1fr;
  gap: 1ch;
}

