  mem: "#b388ff",
  net: "#26c6da",
  key: "#ff9800",
  sel: "#0b4a6f",
};
const PALETTES: Record<string, typeof BTOP_DEFAULT> = {
  nord: {
    g: ["#a3be8c", "#ebcb8b", "#d08770", "#bf616a"],
    mem: "#b48ead",
    net: "#88c0d0",
