/* floating app windows (code, notes, files, music) */
.app-win {
  position: fixed;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: var(--radius, 8px);
  box-shadow: 0 24px 70px rgb(0 0 0 / 0.45), 0 0 0 1px color-mix(in srgb, var(--line) 60%, transparent);
  /* hyprland's default: animation = windows, 1, 7, myBezier, popin 80% (bezier 0.05, 0.9, 0.1, 1.05) */
  animation: app-in 420ms cubic-bezier(0.05, 0.9, 0.1, 1.05) both;
}
.app-win.closing {
  animation: app-out 200ms cubic-bezier(0.3, 0, 0.8, 0.15) both;
  pointer-events: none;
}
.app-win.max {
  left: 0 !important;
  right: 0;
  top: calc(var(--bar-h) + env(safe-area-inset-top, 0px));
  bottom: 0;
  width: auto !important;
  height: auto !important;
  border-radius: 0;
}
