.app-moving, .app-moving * { user-select: none !important; cursor: grabbing !important; }
.app-moving iframe { pointer-events: none; }
.app-resize { position: absolute; right: 0; bottom: 0; width: 16px; height: 16px; cursor: nwse-resize; z-index: 5; }
@keyframes app-in { from { opacity: 0; transform: scale(0.8); } }
@keyframes app-out { to { opacity: 0; transform: scale(0.8); } }
@media (prefers-reduced-motion: reduce) { .app-win, .app-win.closing { animation-duration: 1ms; } }

.app-frame { display: flex; flex-direction: column; height: 100%; min-height: 0; background: var(--win-focus); border: var(--border-w, 1px) solid var(--line); border-radius: inherit; overflow: hidden; color: var(--fg); }
