.app-body { flex: 1; min-height: 0; position: relative; }
.app-loading { height: 100%; display: flex; align-items: center; justify-content: center; gap: 10px; background: var(--win-focus); border: 1px solid var(--line); border-radius: inherit; color: var(--muted); font-family: var(--font-mono); font-size: 12.5px; }
.app-spin { width: 14px; height: 14px; border-radius: 50%; border: 2px solid var(--line); border-top-color: var(--fg); animation: app-spin 0.8s linear infinite; }
@keyframes app-spin { to { transform: rotate(1turn); } }
