.app-input:focus { border-color: var(--line-focus); }

/* notes */
.notes { display: grid; grid-template-columns: 220px 1fr; height: 100%; min-height: 0; }
.notes-list { display: flex; flex-direction: column; gap: 2px; padding: 10px 8px; border-right: 1px solid var(--line); overflow: auto; background: var(--win); }
.notes-list .app-input { margin-bottom: 6px; }
