.notes-doc pre { border: 1px solid var(--line); border-radius: 6px; padding: 12px 14px; overflow-x: auto; font-size: 12px; line-height: 1.45; color: var(--fg); margin: 4px 0 14px; }
.notes-doc a { color: var(--fg); text-decoration: underline; text-underline-offset: 3px; }
@media (max-width: 720px) { .notes { grid-template-columns: 1fr; grid-template-rows: auto 1fr; } .notes-list { flex-direction: row; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--line); } .notes-list .app-input { display: none; } .notes-list button { flex: none; } }

/* files (yazi) */
.app-term { text-align: center; padding-left: 32px; }
.files { display: flex; flex-direction: column; height: 100%; min-height: 0; font-family: var(--font-mono); font-size: 12.5px; outline: 0; line-height: 1.55; }
.yz-head { display: flex; justify-content: space-between; gap: 10px; padding: 4px 10px 2px; white-space: nowrap; overflow: hidden; flex: none; }
.yz-path { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.yz-dir { color: var(--accent); font-weight: 600; }
.yz-file { color: var(--fg); }
.yz-tabs span { padding: 0 7px; color: var(--faint); }
.yz-tabs span.on { background: var(--accent); color: var(--bg); font-weight: 600; }
.files-cols { flex: 1; min-height: 0; display: grid; grid-template-columns: 1fr 4fr 3fr; padding: 2px 0; }
.files-col { overflow: auto; padding: 0 4px; min-width: 0; }
.files-col + .files-col { border-left: 1px solid var(--line); }
.files-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; width: 100%; padding: 0 6px; text-align: left; color: var(--fg); white-space: nowrap; }
.files-row.dir .files-name { color: var(--accent); font-weight: 600; }
.files-row.on { background: color-mix(in srgb, var(--accent) 85%, var(--bg)); }
.files-row.on .files-name, .files-row.on .files-size, .files-row.on .yz-i { color: var(--bg) !important; }
.files-row.on.dim { background: color-mix(in srgb, var(--fg) 11%, transparent); }
