.files-row.on.dim .yz-i { color: inherit !important; }
.files-row.static { cursor: default; }
.files-name { display: flex; align-items: center; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.yz-i { display: inline-flex; width: 16px; justify-content: center; margin-right: 7px; flex: none; }
.files-size { color: var(--faint); flex: none; }
.files-preview pre { margin: 0; padding: 0 8px; white-space: pre-wrap; word-break: break-word; color: var(--fg); font: inherit; font-size: 12px; line-height: 1.5; }
.yz-status { display: flex; justify-content: space-between; align-items: center; gap: 8px; white-space: nowrap; overflow: hidden; font-size: 11.5px; flex: none; }
.yz-l, .yz-r { display: flex; align-items: center; min-width: 0; }
.yz-mode { background: var(--accent); color: var(--bg); font-weight: 700; padding: 1px 9px; }
.yz-chip { background: color-mix(in srgb, var(--fg) 12%, transparent); color: var(--fg); padding: 1px 9px; }
