.vsc-term { margin: 0; padding: 4px 14px; font-family: "Geist Mono", monospace; font-size: 12px; color: var(--muted); white-space: pre-wrap; }

/* status bar */
.vsc-status { display: flex; align-items: center; gap: 2px; height: 24px; padding: 0 8px 0 0; border-top: 1px solid var(--line); background: var(--win); font-size: 11.5px; color: var(--muted); flex: none; overflow: hidden; white-space: nowrap; }
.vsc-status > button, .vsc-status > span:not(.vsc-grow):not(.vsc-remote) { display: inline-flex; align-items: center; gap: 4px; padding: 0 7px; height: 24px; }
.vsc-status > button:hover { background: color-mix(in srgb, var(--fg) 9%, transparent); color: var(--fg); }
.vsc-status .vsc-ico { width: 13px; height: 13px; }
.vsc-remote { display: grid; place-items: center; height: 24px; width: 34px; background: var(--accent); color: var(--bg); margin-right: 4px; }
.vsc-grow { flex: 1; }

/* quick open */
.vsc-quick-wrap { position: absolute; inset: 0; z-index: 40; display: flex; justify-content: center; padding-top: 38px; background: transparent; }
.vsc-quick { width: min(560px, calc(100% - 24px)); max-height: 380px; display: flex; flex-direction: column; background: var(--win); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 16px 50px rgb(0 0 0 / 0.45); overflow: hidden; align-self: flex-start; }
.vsc-quick input { margin: 6px; padding: 6px 9px; background: var(--vsc-ed); border: 1px solid var(--accent); border-radius: 5px; outline: 0; color: var(--fg); font: inherit; }
.vsc-quick-list { overflow: auto; padding: 0 4px 6px; }
.vsc-quick-list button { display: flex; align-items: center; gap: 8px; width: 100%; padding: 4px 8px; border-radius: 4px; text-align: left; }
.vsc-quick-list button.on { background: color-mix(in srgb, var(--accent) 24%, transparent); }

/* toast */
.vsc-toast { position: absolute; right: 14px; bottom: 34px; z-index: 50; max-width: min(420px, calc(100% - 28px)); padding: 9px 13px; border-radius: 6px; background: var(--win); border: 1px solid var(--line); color: var(--fg); box-shadow: 0 10px 30px rgb(0 0 0 / 0.35); font-family: "Geist Mono", monospace; font-size: 12px; }
.vsc-toast.ok { border-color: color-mix(in srgb, #3fb950 60%, var(--line)); }
.vsc-toast.err { border-color: color-mix(in srgb, #f14c4c 60%, var(--line)); }

/* narrow screens: sidebar overlays the editor, fewer status items */
@media (max-width: 760px) {
  .vsc-menus { visibility: hidden; width: 0; }
  .vsc-title { grid-template-columns: 0 1fr auto; }
  .vsc-side { position: absolute; left: 45px; top: 32px; bottom: 24px; z-index: 20; background: var(--win); box-shadow: 8px 0 30px rgb(0 0 0 / 0.35); }
  .vsc-hide-sm { display: none !important; }
}

